/*
 * studio.js — interface e orquestração.
 *
 * A página do Estúdio é quem faz o trabalho pesado, e não o service worker:
 * ela roda na origem chrome-extension:// com host_permissions, então busca
 * qualquer recurso sem esbarrar em CORS, e sobrevive à captura inteira
 * (o service worker seria desligado no meio).
 *
 * A tela tem três estados — configurar, executar, concluir — e só um aparece
 * por vez. Durante a captura não há nada para ajustar, então o formulário sai
 * de cena e dá lugar ao progresso.
 *
 * Antes deles vem a porta: sem login, a tela de entrar; logado sem assinatura
 * ativa, a de assinar. A assinatura é conferida de novo a cada captura.
 */

import { runCapture, DEFAULTS } from '../core/capture.js';
import { DirectoryWriter, ZipWriterSink, supportsDirectoryPicker } from '../core/writer.js';
import { formatBytes } from '../core/util.js';
import * as conta from '../conta/conta.js';
import { CHECKOUT_URL } from '../conta/config.js';

const $ = (id) => document.getElementById(id);

const tela = {
  carregando: $('tela-carregando'),
  login: $('tela-login'),
  assinar: $('tela-assinar'),
  form: $('tela-form'),
  progresso: $('tela-progresso'),
  fim: $('tela-fim')
};

const el = {
  alvo: $('alvo'),
  alvoInfo: $('alvo-info'),
  usarAba: $('usar-aba'),
  capturar: $('capturar'),
  nova: $('nova'),
  status: $('status'),
  topbarNote: $('topbar-note'),
  runTitle: $('run-title'),
  runPct: $('run-pct'),
  rail: $('rail'),
  steps: $('steps'),
  log: $('log'),
  resultado: $('resultado'),
  cPaginas: $('c-paginas'),
  cRecursos: $('c-recursos'),
  cBytes: $('c-bytes'),
  cFalhas: $('c-falhas'),
  statFalhas: $('stat-falhas'),
  numPaginas: $('num-paginas'),
  numRecursos: $('num-recursos'),
  numGravados: $('num-gravados'),
  destino: $('opt-destino'),
  destinoHint: $('destino-hint')
};

let alvoTabId = null;
let rodando = false;

// O atalho gerado depende do sistema de quem captura.
const NO_WINDOWS = /Win/i.test(navigator.userAgent);
const PLATAFORMA = NO_WINDOWS ? 'windows' : 'unix';
const ATALHO = NO_WINDOWS ? 'ABRIR SITE.cmd' : 'ABRIR SITE.command';

/* ─────────────────────────────── perfis ──────────────────────────────── */

const PERFIS = {

content.content:
1	/* Service worker minimo: o trabalho pesado acontece na pagina do Estudio,
2	   que tem host_permissions e pode buscar cross-origin sem esbarrar em CORS. */
3	
4	chrome.action.onClicked.addListener(async (tab) => {
5	  const url = chrome.runtime.getURL('src/studio/studio.html') +
6	    (tab && tab.id ? ('?tab=' + tab.id) : '');
7	  await chrome.tabs.create({ url, index: tab ? tab.index + 1 : undefined });
8	});
9	
10	chrome.runtime.onInstalled.addListener((d) => {
11	  // Registro que tenha sobrado de uma versao anterior nao pode ficar ativo.
12	  desarmar().catch(() => {});
13	  if (d.reason === 'install') {
14	    chrome.tabs.create({ url: chrome.runtime.getURL('src/studio/studio.html') + '?welcome=1' });
15	  }
16	});
17	
18	/*
19	 * Coletores sob demanda.
20	 *
21	 * hooks.js intercepta fetch/XHR e guarda o corpo das respostas. Isso so faz
22	 * sentido na aba que esta sendo capturada — ficar ligado em toda pagina que o
23	 * usuario abre copiaria para a memoria respostas do banco, do e-mail, de tudo,
24	 * e deixaria o navegador mais pesado sem motivo. Entao os scripts so ficam
25	 * registrados enquanto uma captura roda: o Estudio "arma" no inicio (a
26	 * captura recarrega a pagina logo em seguida, e os hooks entram antes do
27	 * primeiro script do site) e "desarma" no fim.
28	 *
29	 * Se o Estudio fechar no meio, a aba dele sai de `estudios` e, quando nao
30	 * sobra nenhum, o registro vai embora junto.
31	 */
32	const IDS = ['exbc-hooks', 'exbc-bridge'];
33	const K_ESTUDIOS = 'bg.estudiosArmados';
34	
35	const SCRIPTS = [
36	  {
37	    id: 'exbc-hooks', js: ['src/content/hooks.js'], world: 'MAIN',
38	    matches: ['http://*/*', 'https://*/*'], runAt: 'document_start',
39	    allFrames: true, persistAcrossSessions: false
40	  },
41	  {
42	    id: 'exbc-bridge', js: ['src/content/bridge.js'], world: 'ISOLATED',
43	    matches: ['http://*/*', 'https://*/*'], runAt: 'document_start',
44	    allFrames: true, persistAcrossSessions: false
45	  }
46	];
47	
48	async function estudios() {
49	  try { return (await chrome.storage.session.get(K_ESTUDIOS))[K_ESTUDIOS] || []; } catch { return []; }
50	}
51	
52	async function armar(tabEstudio) {
53	  const lista = new Set(await estudios());
54	  if (tabEstudio != null) lista.add(tabEstudio);
55	  await chrome.storage.session.set({ [K_ESTUDIOS]: [...lista] });
56	  const ja = await chrome.scripting.getRegisteredContentScripts({ ids: IDS });
57	  if (ja.length === IDS.length) return;
58	  if (ja.length) await chrome.scripting.unregisterContentScripts({ ids: ja.map((s) => s.id) });
59	  await chrome.scripting.registerContentScripts(SCRIPTS);
60	}
61	
62	async function desarmar(tabEstudio) {
