192	  const params = new URLSearchParams(location.search);
193	  const fromParam = params.get('tab');
194	
195	  let tab = null;
196	  if (fromParam) {
197	    try { tab = await chrome.tabs.get(+fromParam); } catch { tab = null; }
198	  }
199	  if (!tab || !/^https?:/.test(tab.url || '')) {
200	    const [ativa] = await chrome.tabs.query({ active: true, lastFocusedWindow: true });
201	    if (ativa && /^https?:/.test(ativa.url || '')) tab = ativa;
202	    else {
203	      const todas = await chrome.tabs.query({});
204	      tab = todas.find((t) => /^https?:/.test(t.url || '')) || null;
205	    }
206	  }
207	
208	  if (tab) {
209	    alvoTabId = tab.id;
210	    el.alvo.value = tab.url;
211	    el.alvoInfo.textContent = (tab.title || '').slice(0, 110) || 'Aba selecionada';
212	  } else {
213	    el.alvoInfo.textContent = 'Abra o site numa aba e clique em "Aba atual".';
214	  }
215	}
