217	/* ──────────────────────────── telas e passos ─────────────────────────── */
218	
219	function mostrar(qual) {
220	  for (const [nome, t] of Object.entries(tela)) t.hidden = nome !== qual;
221	  window.scrollTo({ top: 0, behavior: 'smooth' });
222	}
223	
224	const ORDEM = ['paginas', 'recursos', 'reescrita', 'runtime', 'design', 'gravacao'];
225	let faseAtual = -1;
226	
227	/*
228	 * Peso de cada fase na barra. Numa captura de uma página só, quase todo o tempo
229	 * real está em baixar. Numa de site inteiro não: visitar seis páginas — navegar,
230	 * rolar cada uma até o fim, esperar o lazy-load — leva minutos, e reservar 10%
231	 * para isso deixa a barra praticamente parada justo na parte mais demorada.
232	 */
233	const PESO_PAGINA_UNICA = [0.1, 0.52, 0.11, 0.04, 0.06, 0.17];
234	const PESO_SITE_INTEIRO = [0.3, 0.38, 0.09, 0.03, 0.05, 0.15];
235	let pesos = PESO_PAGINA_UNICA;
236	
237	function acenderFase(chave) {
238	  const i = ORDEM.indexOf(chave);
239	  if (i < 0) return;
240	  faseAtual = i;
241	  for (const linha of el.steps.querySelectorAll('.stepline')) {
242	    const pos = ORDEM.indexOf(linha.dataset.fase);
243	    linha.dataset.state = pos < i ? 'feito' : pos === i ? 'ativo' : '';
244	  }
245	  const base = pesos.slice(0, i).reduce((a, b) => a + b, 0);
246	  definirProgresso(base * 100);
247	}
248	
249	function concluirFases() {
250	  for (const linha of el.steps.querySelectorAll('.stepline')) linha.dataset.state = 'feito';
251	  definirProgresso(100);
252	}
253	
254	let pctMostrado = 0;
255	function definirProgresso(pct) {
256	  // Só avança: recuar a barra passa a impressão de que algo deu errado.
257	  pctMostrado = Math.max(pctMostrado, Math.min(100, pct));
258	  el.rail.style.width = pctMostrado.toFixed(1) + '%';
259	  el.runPct.textContent = Math.round(pctMostrado) + '%';
260	}
261	
262	/* ─────────────────────────────── log ─────────────────────────────────── */
263	
264	function log(nivel, msg) {
265	  const d = document.createElement('div');
266	  d.className = nivel;
267	  const hora = new Date().toLocaleTimeString('pt-BR', { hour12: false });
268	  d.textContent = `${hora}  ${msg}`;
269	  el.log.appendChild(d);
270	  el.log.scrollTop = el.log.scrollHeight;
271	  while (el.log.childElementCount > 600) el.log.removeChild(el.log.firstChild);
272	}
273	
274	const ui = {
275	  log,
276	  stage(nome, chave) {
277	    el.runTitle.textContent = nome;
278	    if (chave) acenderFase(chave);
279	    log('info', `[ ${nome} ]`);
280	  },
281	  progress(p) {
282	    if (p.pages != null) {
283	      el.cPaginas.textContent = p.pages;
284	      el.numPaginas.textContent = p.pagesTotal && p.pagesTotal > p.pages
285	        ? `${p.pages} / ${p.pagesTotal}` : p.pages;
286	    }
287	    if (p.fetched != null) {
288	      el.cRecursos.textContent = p.fetched;
289	      el.numRecursos.textContent = p.total ? `${p.fetched} / ${p.total}` : p.fetched;
290	    }
291	    if (p.failed != null) {
292	      el.cFalhas.textContent = p.failed;
293	      el.statFalhas.classList.toggle('alert', p.failed > 0);
294	    }
295	    if (p.bytes != null) el.cBytes.textContent = formatBytes(p.bytes);
296	    if (p.written != null) el.numGravados.textContent = `${p.written} / ${p.total}`;
297	
298	    // Progresso dentro da fase corrente, sem passar do início da próxima.
299	    //
300	    // A fase de páginas não tem total conhecido — a fila cresce enquanto os
301	    // links aparecem. Usar "visitadas / (visitadas + na fila)" resolve: a razão
302	    // tende a 1 conforme a fila esvazia, e como a barra só avança, uma fila que
303	    // cresce faz ela parar em vez de voltar.
304	    const i = Math.max(0, faseAtual);
305	    const base = pesos.slice(0, i).reduce((a, b) => a + b, 0);
306	
307	    let feito = null;
308	    if (p.total) feito = (p.written ?? p.fetched ?? 0) / p.total;
309	    else if (p.pagesTotal) feito = (p.pages + (p.emAndamento || 0) * 0.5) / p.pagesTotal;
310	
311	    if (feito != null) definirProgresso((base + pesos[i] * Math.min(1, feito)) * 100);
312	  }
313	};
314	
315	/* ────────────────────────────── captura ──────────────────────────────── */
316	
317	async function capturar() {
318	  if (rodando) return;
319	
320	  const url = el.alvo.value.trim();
321	  if (!/^https?:\/\//i.test(url)) {
322	    erro('Informe um endereço começando com http:// ou https://');
323	    return;
324	  }
325	  if (!alvoTabId) {
326	    erro('Nenhuma aba alvo. Clique em "Aba atual".');
327	    return;
328	  }
329	
330	  const opts = { ...lerOpcoes(), plataforma: PLATAFORMA };
