  try {
    const u = new URL(url);
    const base = u.host.replace(/^www\./, '').replace(/[^\w.-]/g, '_');
    return `${base}-${new Date().toISOString().slice(0, 10)}`;
  } catch { return 'site-baixado'; }
}

