/* ═══════════════════════════ login e assinatura ═════════════════════════ */

/* Um cartão centrado, com a logo: a tela de entrar tem cara de tela de entrar,
   não de mais um formulário do Estúdio. */
.acesso-main { padding-top: clamp(24px, 8vh, 72px); }

.acesso-card {
  max-width: 420px;
  margin: 0 auto;
  padding: 36px 32px 28px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  display: flex;
  flex-direction: column;
  gap: 16px;
  text-align: center;
  animation: rise 0.5s var(--ease) both;
}

.acesso-logo { width: 56px; height: 56px; border-radius: 14px; margin: 0 auto 2px; }

.acesso-card h1 { font-size: 26px; margin: 0; }
.acesso-sub { margin: -8px 0 4px; font-size: 13.5px; color: var(--fg-mute); line-height: 1.55; }

.btn-largo { width: 100%; justify-content: center; }
a.btn { text-decoration: none; }

/* o botão do Google segue o padrão da própria Google: branco, com a marca colorida */
.btn-google {
  justify-content: center;
  gap: 12px;
  padding: 12px 20px;
  background: #ffffff;
  color: #1f1f1f;
  font-weight: 550;
}
.btn-google:hover { background: #f2f2f2; transform: translateY(-1px); }
.btn-google:disabled { opacity: 0.5; cursor: wait; transform: none; }
.btn-google svg { width: 18px; height: 18px; flex: none; }
#google-status:empty { display: none; }

.acesso-ou {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 2px 0;
  font-size: 12px;
  color: var(--fg-mute);
}
.acesso-ou::before, .acesso-ou::after { content: ""; flex: 1; height: 1px; background: var(--line); }

.acesso-form { display: flex; flex-direction: column; gap: 12px; text-align: left; }
.acesso-label { font-size: 12.5px; color: var(--fg-dim); }
.acesso-label b { color: var(--fg); font-weight: 550; }

.acesso-card .target { padding: 13px 16px; }
.acesso-card .target input { font-size: 15px; }
.acesso-card .target input.codigo {
  font-size: 22px;
  letter-spacing: 0.35em;
  font-variant-numeric: tabular-nums;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.acesso-card .hint { margin: 0; min-height: 0; text-align: center; }
.acesso-card .hint:empty { display: none; }

.acesso-links {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin: 2px 0 0;
  font-size: 12.5px;
  color: var(--fg-mute);
}
.link:disabled { color: var(--fg-mute); cursor: default; text-decoration: none; }

.acesso-rodape {
  margin: 8px 0 0;
  padding-top: 16px;
  border-top: 1px solid var(--line);
  font-size: 12.5px;
  color: var(--fg-mute);
}
.acesso-rodape a { color: var(--accent); text-underline-offset: 3px; }

/* ══════════════════════════ troca de estados ════════════════════════════ */

[hidden] { display: none !important; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* pastilhas do resumo do design system */
.ds-chips { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 4px; }
.ds-chips span {
  background: var(--surface-2);
  border-radius: 99px;
  padding: 5px 12px;
  font-size: 11.5px;
  color: var(--fg-mute);
}
.ds-chips b { color: var(--fg); font-weight: 600; }

/* Plano gratuito: quantos downloads ainda restam no mês. */
.gratis {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin: 18px 0 28px;
  padding: 12px 16px;
  border: 1px solid var(--line-mid);
  border-radius: 12px;
  background: var(--accent-soft);
}
.gratis-texto { margin: 0; font-size: 13px; line-height: 1.5; }
.gratis-texto b { color: var(--accent); }
.gratis-cta {
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 3px;
  white-space: nowrap;
}
.gratis-cta[hidden] { display: none; }

