 'src/core/design-live.js':[('Gerado pelo Extrator de Sites Brave Cross.','Gerado pelo Extrator de Sites.')],
 'src/core/writer.js':[("'Gerado pelo Extrator de Sites Brave Cross'","'Gerado pelo Extrator de Sites'")],
 'src/templates/runtime.js':[('"Extrator de Sites Brave Cross"','"Extrator de Sites"')],
 'src/templates/worker-runtime.js':[('"Extrator de Sites Brave Cross"','"Extrator de Sites"')],
 'src/templates/servidor.py.tpl':[('"Extrator de Sites Brave Cross"','"Extrator de Sites"')],
}
for p,rs in reps.items():
