/*
 * Estúdio — sistema visual.
 *
 * Três decisões governam tudo aqui:
 *
 * 1. Uma escolha por vez. A tela pede o alvo, depois o perfil, depois executa.
 *    Todo ajuste fino vive atrás de um disclosure — quem precisa, abre.
 * 2. Escuro comprometido. Sem tema claro paralelo: uma paleta só, calibrada,
 *    rende mais contraste e mais personalidade do que duas medianas.
 * 3. O espaço é o ornamento. Quase não há bordas nem sombras; a hierarquia vem
 *    de escala tipográfica, respiro e um único acento.
 */

:root {
  color-scheme: dark;

  --bg: #0a0a0b;
  --surface: #101012;
  --surface-2: #16161a;
  --surface-3: #1d1d22;

  --line: rgba(255, 255, 255, 0.06);
  --line-mid: rgba(255, 255, 255, 0.11);
  --line-strong: rgba(255, 255, 255, 0.2);

  --fg: #f4f4f5;
  --fg-dim: #a1a1aa;
  --fg-mute: #83838f;

  /* Acento unico. Texto sobre ele e sempre --accent-fg (escuro): 17.1:1.
     Branco sobre este lima da 1.2:1 e nao pode ser usado. */
  --accent: #d4ff3f;
  --accent-dim: #a8cc2f;
  --accent-fg: #0a0a0b;
  --accent-soft: rgba(212, 255, 63, 0.11);

  --ok: #5ee39b;
  --warn: #fbbf24;
  --err: #fb7185;

  --r-sm: 8px;
  --r-md: 12px;
  --r-lg: 16px;

  --ease: cubic-bezier(0.22, 0.61, 0.36, 1);
}

* { box-sizing: border-box; }

html { background: var(--bg); }

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font: 400 13.5px/1.6 ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

::selection { background: var(--accent); color: var(--accent-fg); }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ══════════════════════════════ cabeçalho ═══════════════════════════════ */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 32px;
  border-bottom: 1px solid var(--line);
}

